//! P0 (BL036/BL018/BL019/BL082.17): the pinned pilot vignette corpus, run against the Rust core.
//!
//! `docs/migration/fixtures/pilot-fx/cases.json` holds small cases whose expectations were derived
//! from the PILOT's source formulas by `scripts/pilot-fx-corpus.py` (see `manifest.json` for the
//! origin snapshot, the blob ids and sha256 of every source, and the blockers). This test is the
//! other half: the Rust core must give the same passes, the same pixels and the same gesture
//! behaviour. The corpus is generated by an independent implementation (Python, written from the
//! origin's GLSL and colour chunks), so agreeing here is two derivations of the origin agreeing,
//! never the Rust reference being compared with itself.
//!
//! What it does NOT prove: the origin's golden PNG (it needs the origin's harness, which is not
//! run here: manifest blocker `ORIGIN_GOLDEN_NOT_COMPARABLE`) and the origin's own outputs (blocker
//! `ORIGIN_NOT_EXECUTED`). The corpus hash and the origin blobs are checked by
//! `scripts/pilot-fx-corpus.py verify [--origin PATH]`.

use core::prelude::v1::test;
use serde_json::{Value, json};
use tessel_editor_core::directed_scene::DirectedScene;
use tessel_editor_core::directed_scene::fx;
use tessel_editor_core::state::ProjectSettings;
use tessel_editor_core::{CommandError, EditorState, headless};

const CORPUS: &str = include_str!("../../../docs/migration/fixtures/pilot-fx/cases.json");
const MANIFEST: &str = include_str!("../../../docs/migration/fixtures/pilot-fx/manifest.json");
const BASE: &str =
    include_str!("../../../docs/migration/fixtures/bundles/valid-minimal-continuous.bundle.json");

fn corpus() -> Value {
    serde_json::from_str(CORPUS).unwrap()
}

fn bundle_with(fx: &Value) -> Value {
    let mut bundle: Value = serde_json::from_str(BASE).unwrap();
    bundle["fx"] = fx.clone();
    bundle
}

fn session(fx: &Value) -> EditorState {
    let mut state = EditorState::empty(&ProjectSettings::default()).unwrap();
    run(
        &mut state,
        json!({"op":"scene.attach","id":"street","bundle":bundle_with(fx)}),
    );
    state
}

fn run(state: &mut EditorState, request: Value) -> Value {
    headless::execute(state, &request).unwrap_or_else(|error| panic!("{request}: {error:?}"))
}

fn refuse(state: &mut EditorState, request: Value) -> CommandError {
    match headless::execute(state, &request) {
        Ok(answer) => panic!("{request} should have been refused, got {answer}"),
        Err(error) => error,
    }
}

fn near(left: f64, right: f64) -> bool {
    (left - right).abs() < 1e-9
}

fn unhex(text: &str) -> Vec<u8> {
    (0..text.len() / 2)
        .map(|index| u8::from_str_radix(&text[index * 2..index * 2 + 2], 16).unwrap())
        .collect()
}

/// The largest channel difference between two pictures of the same size.
fn worst_difference(left: &[u8], right: &[u8]) -> u8 {
    assert_eq!(left.len(), right.len());
    left.iter()
        .zip(right)
        .map(|(a, b)| a.abs_diff(*b))
        .max()
        .unwrap_or(0)
}

#[test]
fn the_manifest_names_the_origin_the_sources_and_the_blockers_it_could_not_close() {
    let manifest: Value = serde_json::from_str(MANIFEST).unwrap();
    assert_eq!(manifest["origin"]["snapshot"], "d40ac3f7c0");
    assert!(
        manifest["origin"]["snapshot_commit"]
            .as_str()
            .unwrap()
            .starts_with("d40ac3f7c0")
    );
    assert_eq!(manifest["corpus"]["file"], "cases.json");
    assert_eq!(manifest["corpus"]["sha256"].as_str().unwrap().len(), 64);
    let sources = manifest["sources"].as_array().unwrap();
    for source in sources {
        assert_eq!(source["git_blob"].as_str().unwrap().len(), 40, "{source}");
        assert_eq!(source["sha256"].as_str().unwrap().len(), 64, "{source}");
    }
    let paths: Vec<_> = sources
        .iter()
        .map(|s| s["path"].as_str().unwrap())
        .collect();
    for needed in [
        "packages/scene-engine/src/runtime/fx/shaders/vignette.ts",
        "packages/scene-engine/src/fx/fx-clip-sample.ts",
        "packages/scene-engine/src/fx/catalog/__golden__/vignette.png",
    ] {
        assert!(paths.contains(&needed), "{needed}");
    }
    let blockers: Vec<_> = manifest["blockers"]
        .as_array()
        .unwrap()
        .iter()
        .map(|b| b["id"].as_str().unwrap())
        .collect();
    assert!(blockers.contains(&"ORIGIN_GOLDEN_NOT_COMPARABLE"));
    assert!(blockers.contains(&"ORIGIN_NOT_EXECUTED"));
}

#[test]
fn the_passes_at_each_frame_are_the_pilots_in_amount_weight_and_order() {
    let corpus = corpus();
    let mut compared = 0;
    for case in corpus["cases"].as_array().unwrap() {
        if case["kind"] != "frames" {
            continue;
        }
        let id = case["id"].as_str().unwrap();
        let mut state = session(&case["fx"]);
        for frame in case["frames"].as_array().unwrap() {
            let at = frame["frame"].as_i64().unwrap();
            let answer = run(
                &mut state,
                json!({"op":"scene.fx.frame","scene":"street","frame":at}),
            );
            let got = answer["passes"].as_array().unwrap();
            let want = frame["passes"].as_array().unwrap();
            assert_eq!(got.len(), want.len(), "{id} frame {at}: pass count");
            for (got, want) in got.iter().zip(want) {
                assert_eq!(got["clipId"], want["clip"], "{id} frame {at}: order");
                assert_eq!(got["trackId"], want["track"], "{id} frame {at}");
                assert_eq!(got["frameInClip"], want["frame_in_clip"], "{id} frame {at}");
                for key in ["weight", "amount"] {
                    assert!(
                        near(got[key].as_f64().unwrap(), want[key].as_f64().unwrap()),
                        "{id} frame {at}: {key} is {} but the pilot says {}",
                        got[key],
                        want[key]
                    );
                }
                compared += 1;
            }
        }
    }
    assert!(compared >= 20, "the corpus compared too little: {compared}");
}

#[test]
fn the_pixels_are_the_pilots_shader_and_a_tampered_expectation_is_caught() {
    let corpus = corpus();
    let mut compared = 0;
    for case in corpus["cases"].as_array().unwrap() {
        if case["kind"] != "pixels" {
            continue;
        }
        let id = case["id"].as_str().unwrap();
        let (width, height) = (
            case["width"].as_u64().unwrap() as usize,
            case["height"].as_u64().unwrap() as usize,
        );
        let input = unhex(case["input_rgba_hex"].as_str().unwrap());
        let expected = unhex(case["expected_rgba_hex"].as_str().unwrap());
        let tolerance = case["tolerance_per_channel"].as_u64().unwrap() as u8;

        let scene = DirectedScene::import_value(bundle_with(&case["fx"])).unwrap();
        let mut rgba = input.clone();
        for pass in scene.bundle().fx_passes(case["frame"].as_i64().unwrap()) {
            assert!(
                fx::apply_pass_to_rgba8(&pass, &mut rgba, width, height),
                "{id}"
            );
        }
        let worst = worst_difference(&rgba, &expected);
        assert!(
            worst <= tolerance,
            "{id}: worst channel difference {worst} > {tolerance}"
        );
        assert_eq!(
            case["identity"].as_bool().unwrap(),
            rgba == input,
            "{id}: identity must match the pilot's (no effect or amount 0 keeps the bytes)"
        );
        if case["identity"].as_bool().unwrap() {
            assert_eq!(rgba, input, "{id}: byte for byte");
        } else {
            assert_ne!(rgba, input, "{id}: the effect must change the picture");
        }

        // Negative control: a corpus whose pixel moved by more than the tolerance must not pass.
        let mut tampered = expected.clone();
        let last = tampered.len() - 2;
        tampered[last] = tampered[last].wrapping_add(tolerance + 4);
        if !case["identity"].as_bool().unwrap() {
            assert!(
                worst_difference(&rgba, &tampered) > tolerance,
                "{id}: the comparison is blind to a changed expectation"
            );
        }
        compared += 1;
    }
    assert_eq!(compared, 4);
}

fn intensity_in(state: &mut EditorState, gesture: Option<&str>) -> f64 {
    let mut request = json!({"op":"scene.fx.list","scene":"street"});
    if let Some(gesture) = gesture {
        request["gesture"] = json!(gesture);
    }
    run(state, request)["tracks"][0]["clips"][0]["params"]["intensity"]
        .as_f64()
        .unwrap()
}

fn undo_depth(state: &EditorState) -> u64 {
    state.history.to_json()["undo_depth"].as_u64().unwrap()
}

#[test]
fn the_gesture_behaviours_of_the_pilot_hold_in_the_core() {
    let corpus = corpus();
    let cases = corpus["gesture_cases"].as_array().unwrap();
    assert!(cases.len() >= 6);
    for case in cases {
        let id = case["id"].as_str().unwrap();
        let mut state = session(&case["fx"]);
        let start = undo_depth(&state);
        let mut gesture: Option<String> = None;
        for step in case["steps"].as_array().unwrap() {
            let ops = |value: f64| json!([{"op":"set_param","clip":"v1","param":"intensity","value":value}]);
            match step["do"].as_str().unwrap() {
                "begin" => {
                    let began = run(
                        &mut state,
                        json!({"op":"scene.fx.gesture.begin","scene":"street","clip":"v1"}),
                    );
                    gesture = began["gesture"].as_str().map(str::to_string);
                }
                "update" => {
                    run(
                        &mut state,
                        json!({"op":"scene.fx.gesture.update","gesture":gesture,
                            "ops":ops(step["intensity"].as_f64().unwrap())}),
                    );
                }
                "update_refused" => {
                    let error = refuse(
                        &mut state,
                        json!({"op":"scene.fx.gesture.update","gesture":gesture,
                            "ops":ops(step["intensity"].as_f64().unwrap())}),
                    );
                    assert_eq!(error.code, step["code"].as_str().unwrap(), "{id}");
                }
                "status" => {
                    run(&mut state, json!({"op":"scene.fx.gesture.status"}));
                }
                "commit" => {
                    run(
                        &mut state,
                        json!({"op":"scene.fx.gesture.commit","gesture":gesture}),
                    );
                    gesture = None;
                }
                "cancel" => {
                    run(
                        &mut state,
                        json!({"op":"scene.fx.gesture.cancel","gesture":gesture}),
                    );
                    gesture = None;
                }
                other => panic!("{id}: unknown step {other}"),
            }
        }
        let expect = &case["expect"];
        if let Some(candidate) = expect["candidate_intensity"].as_f64() {
            assert!(
                near(intensity_in(&mut state, gesture.as_deref()), candidate),
                "{id}: the candidate"
            );
        }
        assert_eq!(
            undo_depth(&state) - start,
            expect["undo_entries_added"].as_u64().unwrap(),
            "{id}: undo entries"
        );
        let committed = intensity_in(&mut state, None);
        assert!(
            near(committed, expect["document_intensity"].as_f64().unwrap()),
            "{id}: the document holds {committed}"
        );
        if case.get("divergence").is_some() {
            // A divergence is stated, not hidden: the corpus says what the pilot does and what we do.
            assert!(
                case["divergence"]["origin"].is_string() && case["divergence"]["rust"].is_string()
            );
        }
    }
}

#[test]
fn the_refusals_the_catalog_ranges_imply_are_typed() {
    for case in corpus()["refusals"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let mut state = session(&case["fx"]);
        let before = undo_depth(&state);
        let error = refuse(
            &mut state,
            json!({"op":"scene.fx.edit","scene":"street","ops":[case["op"].clone()]}),
        );
        assert_eq!(error.code, case["code"].as_str().unwrap(), "{id}");
        assert_eq!(
            undo_depth(&state),
            before,
            "{id}: a refusal leaves no entry"
        );
    }
}
